// --- VORTICE PSICHEDELICO (Modalità Texture) ---
// Usa gli slider A e B per modificare l'effetto in tempo reale!

// Impostiamo dei valori di default se gli slider sono a 0
float speed = 5.0;    // animation speed
float scale = 20.0;   // pattern scale

// Spostiamo il centro delle coordinate u,v al centro dello schermo
vec2 center = vec2(u, v) - 0.5;
float dist = length(center);
float angle = atan(center.y, center.x);

// Calcoliamo l'onda in base alla distanza, all'angolo e al TEMPO (t)
float wave = sin(dist * scale - t * speed + angle * 4.0);

// Colori dinamici
float r = 0.5 + 0.5 * wave;
float g = 0.2 + 0.3 * sin(t); // Il verde pulsa dolcemente nel tempo
float b = 0.5 + 0.5 * cos(dist * 10.0 - t);

return vec3(r, g, b);

